head.script:
scwin.checkVal1 = function() {
    return autoComp1.getAttribute('submenuSize') == 'auto';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'autoComp1_itemTable_0') != null;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getDomById($p.id+"autoComp1_itemTable_0").innerText == '[100]대리점사업부';
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'autoComp1').style.width == WebSquare.wUnit.getDomById($p.id + 'autoComp1_itemTable').style.width;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step1. Property 탭에서 submenuSize 가 auto 인지 확인한다.- In the Property tab, verify that submenuSize is auto.
    //Verify 1. submenuSize='auto'
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 브라우저에서 submenu 버튼을 클릭한다.- In the browser, click the submenu button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComp1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. submenu 가 활성화 된다.(width가 동일하게 보여진다.)-The submenu is activated.(The width is shown the same.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "value": "[100]대리점사업부",
        "label": "[100]대리점사업부"
    }];
    dl_autoData.setJSON(jsonData);
    autoComp1.setItemSet("data:dl_autoData", "label", "value");
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
